function result=runV4TrackAFormalR14()
root=v4SetupPaths();c=sf12NoLdroSf11FlowConfig();m=jsondecode(fileread(fullfile(root,'config','paperReceiverParameterManifest_stage3s_v01.json')));p=m.parameters;p.bootstrapStepBins=.05;p.highShiftThresholdBins=100;planHash=v4Sha256(fullfile(root,'R14_STAGE55_CAUSAL_HYPOTHESIS_SELECTION.md'));algorithmSignature=v4Sha256([planHash v4Sha256(fullfile(root,'src','paper_anchor','v4TrackAStage55DualHypothesisDecode.m')) v4Sha256(v4CanonicalJson(p))]);pool=gcp('nocreate');if isempty(pool)||pool.NumWorkers~=2,if ~isempty(pool),delete(pool);end;parpool('local',2);end;cells=cell(20,1);parfor index=1:20,ci=ceil(index/10);si=mod(index-1,10)+1;cells{index}=v4RunTrackAFormalCellR14(root,c,p,algorithmSignature,ci,si);end;result=struct('status','PASS','algorithmVersion','Stage55-A-causal-dual-hypothesis-v11','algorithmSignature',algorithmSignature,'totalPairedPackets',400000,'cells',{cells});folder=fullfile(root,'results','formal','track_a','R14-dual-hypothesis');save(fullfile(folder,'formal_index.mat'),'result','-v7.3');
end
